create index if not exists idx_admin_action_requests_reviewed_by on public.admin_action_requests(reviewed_by); create index if not exists idx_delivery_assignments_proof_id on public.delivery_assignments(proof_id); create index if not exists idx_shipment_events_created_by on public.shipment_events(created_by); create index if not exists idx_shipment_financial_ledger_recorded_by on public.shipment_financial_ledger(recorded_by); drop policy if exists delivery_assignments_staff_select on public.delivery_assignments; drop policy if exists delivery_assignments_staff_write on public.delivery_assignments; create policy delivery_assignments_staff_all on public.delivery_assignments for all to authenticated using ((select exists(select 1 from public.staff s where s.id = (select auth.uid()) and s.is_active = true))) with check ((select exists(select 1 from public.staff s where s.id = (select auth.uid()) and s.is_active = true))); drop policy if exists shipment_events_staff_select on public.shipment_events; drop policy if exists shipment_events_staff_insert on public.shipment_events; drop policy if exists shipment_events_staff_update on public.shipment_events; create policy shipment_events_staff_select on public.shipment_events for select to authenticated using ((select exists(select 1 from public.staff s where s.id = (select auth.uid()) and s.is_active = true))); create policy shipment_events_staff_insert on public.shipment_events for insert to authenticated with check ((select exists(select 1 from public.staff s where s.id = (select auth.uid()) and s.is_active = true)) and created_by = (select auth.uid())); create policy shipment_events_staff_update on public.shipment_events for update to authenticated using ((select exists(select 1 from public.staff s where s.id = (select auth.uid()) and s.is_active = true))) with check ((select exists(select 1 from public.staff s where s.id = (select auth.uid()) and s.is_active = true))); create or replace function public.complete_delivery(p_shipment_id text,p_receiver_name text,p_receiver_phone text,p_note text default null,p_latitude numeric default null,p_longitude numeric default null,p_photo_urls jsonb default '[]'::jsonb,p_signature_url text default null) returns uuid language plpgsql security definer set search_path = public as $$ declare v_uid uuid := auth.uid(); v_staff public.staff%rowtype; v_proof uuid; v_now timestamptz := now(); begin select * into v_staff from public.staff where id=v_uid and is_active=true; if not found then raise exception 'Staff access required'; end if; if not exists(select 1 from public.shipments where id=p_shipment_id) then raise exception 'Shipment not found'; end if; insert into public.delivery_proofs(shipment_id,delivered_at,receiver_name,receiver_phone,signature_url,photo_urls,note,latitude,longitude,created_by) values(p_shipment_id,v_now,p_receiver_name,p_receiver_phone,p_signature_url,p_photo_urls,p_note,p_latitude,p_longitude,v_uid) returning id into v_proof; update public.delivery_assignments set status='delivered',delivered_at=v_now,proof_id=v_proof,updated_at=v_now where shipment_id=p_shipment_id and status in ('assigned','accepted','picked_up','out_for_delivery'); update public.shipments set operational_status='delivered',tracking_updated_at=v_now,current_location_label=coalesce(current_location_label,'Delivered') where id=p_shipment_id; insert into public.shipment_events(shipment_id,event_type,status,location,note,occurred_at,created_by,created_by_name,metadata) values(p_shipment_id,'delivered','delivered',current_setting('request.headers',true),p_note,v_now,v_uid,v_staff.full_name,jsonb_build_object('proof_id',v_proof)); update public.customer_notifications set read_at=read_at where false; insert into public.customer_notifications(customer_user_id,shipment_id,kind,title,body,action_url) select s.customer_user_id,s.id,'shipment_status','Shipment delivered','Your shipment has been delivered.','/tracking.html?tracking='||s.id from public.shipments s where s.id=p_shipment_id and s.customer_user_id is not null; insert into public.staff_activity_log(staff_id,staff_name,action,target_id,details) values(v_uid,v_staff.full_name,'complete_delivery',p_shipment_id,jsonb_build_object('proof_id',v_proof,'receiver_name',p_receiver_name)); return v_proof; end; $$; revoke all on function public.complete_delivery(text,text,text,text,numeric,numeric,jsonb,text) from public; grant execute on function public.complete_delivery(text,text,text,text,numeric,numeric,jsonb,text) to authenticated;;
